props.className:
{cn(
        "relative z-1 h-8 w-7.5 rounded-full border-0 border-none border-current bg-transparent font-chrome text-xs leading-none font-bold text-(--cg-ink-dim) transition-colors duration-200 aria-pressed:text-(--cg-ink) pointer-coarse:h-11 pointer-coarse:w-11",
        className
      )}

label:
{moving
            ? `Preview range, ${(preview.range.end - preview.range.start).toFixed(1)} s from ${formatClockTime(preview.range.start)}`
            : `Preview frame at ${formatClockTime(preview.thumbnailTime)}`}

props.className:
{cn(
            "absolute inset-y-0 left-(--at) z-4 w-(--span) cursor-grab touch-none focus-visible:outline-none data-held:cursor-grabbing",
            "before:absolute before:inset-y-0 before:-left-2.5 before:w-5 focus-visible:before:rounded-sm focus-visible:before:outline-2 focus-visible:before:outline-offset-3 focus-visible:before:outline-white",
          )}

props.aria-label:
{moving
            ? `Preview range, ${(preview.range.end - preview.range.start).toFixed(1)} s from ${formatClockTime(preview.range.start)}`
            : `Preview frame at ${formatClockTime(preview.thumbnailTime)}`}

props.className:
{cn(
          'relative block max-w-full rounded-md transition-shadow focus-visible:outline-2 focus-visible:outline-ring',
          media && 'w-full',
          selected === id &&
            'ring-2 ring-primary ring-offset-2 ring-offset-background',
        )}

{cn(
          'group/thumb relative flex h-13.5 shrink-0 items-center justify-center overflow-hidden rounded text-muted-foreground transition-opacity duration-150 [&:hover]:opacity-80',
          wide ? 'w-auto max-w-24 min-w-13.5' : 'w-13.5',
        )}

{cn(
          'absolute inset-y-0 z-6 my-auto -ml-5.5 flex h-20 w-11 cursor-ew-resize touch-none items-center justify-center transition-left duration-260 ease-seg group-data-resizing/media-resizer:transition-none group-has-data-[playing=true]/media-resizer:pointer-events-none group-has-data-[playing=true]/media-resizer:opacity-0 [@media(max-width:760px)]:hidden',
          innerEdge === 'left' ? 'left-0' : 'left-full',
        )}
